{
  "claims": [
    {
      "agent": "NOC",
      "type": "action",
      "verb": "rollback_model",
      "params": {
        "change": "fraud_model_v2"
      },
      "inject_refs": [
        "S3-I1",
        "S3-I3"
      ],
      "rationale": "Fraud model v2 is falsely refusing legitimate SIM replacements at scale (~2,750 since 08:00), especially for prepaid and roaming customers. Rolling back reduces false positives while known fraud remains blocked.",
      "evidence": [
        {
          "chunk_id": "US-FCC-23-95#0005",
          "quote": "The record reflects that the vast majority of SIM change and port-out requests are legitimate. It also shows that the efficient and effective processing of SIM changes and port-out requests promotes customer choice and competition and prevents interruptions in access to wireless services that are vital to customers' everyday lives."
        }
      ]
    },
    {
      "agent": "NOC",
      "type": "action",
      "verb": "enable_review_queue",
      "params": {
        "queue": "refused_sim_replacement_review"
      },
      "inject_refs": [
        "S3-I3",
        "S3-I4"
      ],
      "rationale": "No human review path exists for refused requests. A review queue gives affected customers a way to contest false positives and restores service.",
      "evidence": [
        {
          "chunk_id": "US-FCC-23-95#0058",
          "quote": "Our requirement that wireless providers maintain a clearly disclosed, transparent, and easy-to-use process for customers to report SIM swap and port-out fraud rests on our concern that customers currently struggle to report SIM swap and port-out fraud to their wireless providers. ... clear methods for reporting SIM swap and port-out fraud that are transparent to customers will ``ensure that customers have easy access to information they need to report SIM swap, port-out, or other fraud.''"
        }
      ]
    },
    {
      "agent": "NOC",
      "type": "obligation",
      "statement": "NOC must preserve legitimate SIM replacement access and provide a transparent, contestable process when automated fraud controls refuse a request.",
      "inject_refs": [
        "S3-I3",
        "S3-I4"
      ],
      "rationale": "Global precedent requires balancing fraud prevention with legitimate access and maintaining customer-facing processes; the incident shows both are failing.",
      "evidence": [
        {
          "chunk_id": "US-FCC-23-95#0005",
          "quote": "...preserves customer choice and competition and prevents interruptions in access to wireless services that are vital to customers' everyday lives."
        }
      ],
      "deadline_hours": 24
    },
    {
      "agent": "REG",
      "type": "action",
      "verb": "open_incident",
      "params": {
        "severity": "high"
      },
      "inject_refs": [
        "S3-I1",
        "S3-I3",
        "S3-I4"
      ],
      "rationale": "A fraud model change caused thousands of legitimate SIM replacement refusals and customer complaints, requiring formal regulatory handling.",
      "evidence": [
        {
          "chunk_id": "US-FCC-23-95#0005",
          "quote": "The record reflects that the vast majority of SIM change and port-out requests are legitimate. It also shows that the efficient and effective processing of SIM changes and port-out requests promotes customer choice and competition and prevents interruptions in access to wireless services that are vital to customers' everyday lives."
        }
      ]
    },
    {
      "agent": "REG",
      "type": "action",
      "verb": "issue_direction",
      "params": {
        "direction": "suspend fraud_model_v2, restore human review, report impact"
      },
      "inject_refs": [
        "S3-I3",
        "S3-I4"
      ],
      "rationale": "The regulator should direct OpCo to stop the harmful false positives and provide an appeal channel before further customer harm.",
      "evidence": [
        {
          "chunk_id": "US-FCC-23-95#0062",
          "quote": "we require wireless providers to maintain a clearly disclosed, transparent, and easy-to-use process for customers to report SIM swap and port-out fraud, promptly investigate and take reasonable steps within their control to remediate such fraud, and, upon request, promptly provide customers with documentation of SIM swap and port-out fraud involving their accounts."
        }
      ]
    },
    {
      "agent": "REG",
      "type": "gap",
      "gap_type": "no_rule",
      "statement": "No identified UAE instrument sets the SIM-swap authentication requirements or the obligation to provide human review/appeal for refused SIM replacements.",
      "inject_refs": [
        "S3-I5"
      ],
      "rationale": "The internal question to the regulator's duty officer reveals uncertainty about the applicable UAE legal basis, leaving enforcement unclear.",
      "evidence": [],
      "global_examples": [
        {
          "chunk_id": "US-FCC-23-95#0004",
          "quote": "The cornerstone of our action is a requirement that wireless providers use secure methods of authenticating customers prior to performing SIM changes and number ports."
        }
      ]
    },
    {
      "agent": "DPA",
      "type": "action",
      "verb": "request_human_review_record",
      "params": {
        "scope": "refused_sim_replacements"
      },
      "inject_refs": [
        "S3-I4"
      ],
      "rationale": "Customer group complains about automated decisions with no explanation or appeal. DPA should obtain records to assess whether individual rights were respected.",
      "evidence": [
        {
          "chunk_id": "US-FCC-23-95#0062",
          "quote": "we require wireless providers to maintain a clearly disclosed, transparent, and easy-to-use process for customers to report SIM swap and port-out fraud, promptly investigate and take reasonable steps within their control to remediate such fraud, and, upon request, promptly provide customers with documentation of SIM swap and port-out fraud involving their accounts."
        }
      ]
    },
    {
      "agent": "DPA",
      "type": "action",
      "verb": "open_investigation",
      "params": {
        "focus": "automated_decision_no_explanation"
      },
      "inject_refs": [
        "S3-I4"
      ],
      "rationale": "Automated refusals without explanation or human intervention may violate data protection principles; an investigation is warranted.",
      "evidence": [
        {
          "chunk_id": "US-FCC-23-95#0058",
          "quote": "...clear methods for reporting SIM swap and port-out fraud that are transparent to customers will ``ensure that customers have easy access to information they need to report SIM swap, port-out, or other fraud.''"
        }
      ]
    },
    {
      "agent": "DPA",
      "type": "gap",
      "gap_type": "no_rule",
      "statement": "No identified UAE data protection rule requires explanation or human review of automated decisions for SIM replacement refusals.",
      "inject_refs": [
        "S3-I4"
      ],
      "rationale": "Available knowledge does not contain a UAE legal basis for contesting automated decisions, leaving data subjects without a clear remedy.",
      "evidence": [],
      "global_examples": [
        {
          "chunk_id": "US-FCC-23-95#0005",
          "quote": "...prevents interruptions in access to wireless services that are vital to customers' everyday lives."
        }
      ]
    },
    {
      "agent": "FIN",
      "type": "action",
      "verb": "instruct_banks",
      "params": {
        "instruction": "enable in-app authentication alternative for customers affected by SIM replacement refusals"
      },
      "inject_refs": [
        "S3-I2"
      ],
      "rationale": "Banks are locking out customers because SMS OTP delivery depends on the customer's SIM. In-app authentication provides a secure alternative.",
      "evidence": [
        {
          "chunk_id": "UAE-PRESS-CBUAE-OTP-2025#0000",
          "quote": "UAE banks will stop sending OTPs via SMS and email for online transactions by July 25, 2025. Customers must authenticate transactions using their mobile banking apps for improved security."
        }
      ]
    },
    {
      "agent": "FIN",
      "type": "action",
      "verb": "request_info",
      "params": {
        "request": "number of affected bank customers and banks impacted by SIM replacement refusals"
      },
      "inject_refs": [
        "S3-I2",
        "S3-I3"
      ],
      "rationale": "FIN needs OpCo data to coordinate with banks and assess the extent of customer lockouts.",
      "evidence": [
        {
          "chunk_id": "UAE-PRESS-CBUAE-OTP-2025#0001",
          "quote": "The regulator said OTPs should not be shared through weak modes of communication, such as SMS and emails, as they are vulnerable and can be compromised."
        }
      ]
    },
    {
      "agent": "FIN",
      "type": "gap",
      "gap_type": "no_owner",
      "statement": "No joint OpCo-bank procedure exists for customers locked out of banking when a telecom fraud control erroneously blocks SIM replacement.",
      "inject_refs": [
        "S3-I2",
        "S3-I3"
      ],
      "rationale": "Affected customers fall between telecom and bank responsibilities; neither has a clear process to restore access quickly.",
      "evidence": [],
      "global_examples": [
        {
          "chunk_id": "UAE-PRESS-CBUAE-OTP-2025#0001",
          "quote": "The regulator said OTPs should not be shared through weak modes of communication, such as SMS and emails, as they are vulnerable and can be compromised."
        }
      ]
    }
  ]
}
